+    OptionMap attributeMap = attributes.build(errorCode);
+    if (hasOperand && hasOperator) {
+        result = Expression(rator, rand, std::move(attributeMap));
+    } else if (hasOperand && !hasOperator) {
+        result = Expression(rand, std::move(attributeMap));
