+        switch (getType()) {
+        case UFMT_LONG:
+        case UFMT_INT64: {
+            return *std::get_if<int64_t>(&contents);
+        }
+        case UFMT_DOUBLE: {
+            return icu::Formattable(*std::get_if<double>(&contents)).getInt64(status);
+        }
+        default: {
+            status = U_INVALID_FORMAT_ERROR;
+            return 0;
+        }
+        }
+    }
